import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useVoidReasons, voidReasonsKey } from './useVoidReasons';

// The sheet's void reasons and the form that adds one (blank, or one already on the list, is refused).
// While the list is not empty, voiding a claim needs a reason chosen from it.
export function VoidReasonPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const reasons = useVoidReasons(sheet);
  const [reason, setReason] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { reason: string }) =>
      postJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { ...body, user }),
    onSuccess: (saved) => {
      setReason('');
      queryClient.setQueryData(voidReasonsKey(sheet), saved);
    },
  });
  return (
    <>
      <ul data-testid="void-reason-list">
        {reasons.map((r) => (
          <li key={r} data-testid={`void-reason-row-${r}`}>{r}</li>
        ))}
      </ul>
      <form
        data-testid="void-reason-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ reason: reason.trim() });
          });
        }}
      >
        <input
          data-testid="void-reason-text"
          value={reason}
          placeholder="Void reason"
          onChange={(e) => {
            setReason(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="void-reason-add">Add void reason</button>
        {add.isError && <span data-testid="void-reason-error" role="alert"> Could not add the void reason: it must not be blank or already on the list.</span>}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export const voidReasonsKey = (sheet: string) => ['sheet', sheet, 'void-reasons'] as const;

/** The sheet's void reasons, in the order added. */
export function useVoidReasons(sheet: string): string[] {
  const { data } = useQuery({
    queryKey: voidReasonsKey(sheet),
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
import { createFileRoute } from '@tanstack/react-router';
import { asString, useSearchParam } from '../url/useSearchParam';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { SheetPicker } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';
import { AsOfControl } from '../features/asof/AsOfControl';
import { RatePanel } from '../features/rates/RatePanel';
import { HolidayPanel } from '../features/holidays/HolidayPanel';
import { VoidReasonPanel } from '../features/voidreasons/VoidReasonPanel';
import { SettingsPanel } from '../features/settings/SettingsPanel';
import { PeriodPanel } from '../features/periods/PeriodPanel';
import { PersonForm } from '../features/people/PersonForm';
import { PeopleList } from '../features/people/PeopleList';
import { SheetHeader } from '../features/header/SheetHeader';
import { AuditViewer } from '../features/audit/AuditViewer';

// The one screen. Signed out it shows only the sign-in form; signed in, the user and the sheet
// picker, and — once a sheet is loaded — that sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useSearchParam('user', asString);
  const [sheet] = useSearchParam('sheet', asString);
  if (user === '') return <SignIn />;
  return (
    <>
      <CurrentUser />
      <SheetPicker />
      {sheet !== '' && (
        <div key={sheet}>
          <SheetHeader />
          <SheetToday />
          <AsOfControl />
          <RatePanel />
          <HolidayPanel />
          <VoidReasonPanel />
          <SettingsPanel />
          <PeriodPanel />
          <PersonForm />
          <PeopleList />
          <AuditViewer />
        </div>
      )}
      {sheet === '' && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}
import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey, tagList, tagsKey, type Claim } from './useClaims';

// The claim form on a person's row: adds a claim to that person, or — while one of their claims'
// editor is open (`editClaim` in the URL) — saves that claim. Opening the editor fills the form
// with the claim's values. A blank date takes the sheet's entry date while set, else its today. A negative amount is a correction,
// which names in "corrects" the number of the SETTLED claim of the same person it corrects.
// A reference (spaces trimmed, blank for none) must not already be used on the sheet, regardless of case.
// Tags are comma separated: each is trimmed and lower-cased, and repeats are dropped (by the server).
export function ClaimForm({ personId, claims }: { personId: string; claims: Claim[] }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [editParam, setEditing] = useSearchParam('editClaim', asString);
  const edited = claims.find((c) => c.id === editParam);
  // A claim not under this person has no editor open here.
  const editing = edited?.id ?? '';
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [corrects, setCorrects] = useState('');
  const [ref, setRef] = useState('');
  const [tags, setTags] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();

  const clear = () => {
    setAmount('');
    setDate('');
    setNote('');
    setCorrects('');
    setRef('');
    setTags('');
  };

  const save = useMutation({
    mutationFn: (body: { amount: string; date: string; note: string; corrects: string; ref: string; tags: string }) =>
      editing !== ''
        ? putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${encodeURIComponent(editing)}`, { ...body, user })
        : postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/claims`,
            { ...body, user },
          ),
    onSuccess: () => {
      clear();
      if (editing !== '') setEditing(undefined);
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      void queryClient.invalidateQueries({ queryKey: tagsKey(sheet) });
    },
  });

  // Opening (or closing) an editor fills the form with that claim's values (or empties it).
  const editedId = edited?.id;
  useEffect(() => {
    save.reset();
    if (edited) {
      setAmount(edited.amount);
      setDate(edited.date);
      setNote(edited.note);
      setCorrects(edited.corrects);
      setRef(edited.ref);
      setTags(tagList(edited.tags));
    } else {
      clear();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editedId]);

  const changed = <T,>(set: (v: T) => void) => (v: T) => {
    set(v);
    save.reset();
  };

  return (
    <form
      data-testid="claim-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          return save.mutateAsync({ amount: amount.trim(), date: date.trim(), note, corrects: corrects.trim(), ref: ref.trim(), tags });
        });
      }}
    >
      <input
        data-testid="claim-form-amount"
        value={amount}
        placeholder="Amount"
        inputMode="decimal"
        onChange={(e) => changed(setAmount)(e.target.value)}
      />{' '}
      <input type="date" data-testid="claim-form-date" value={date} onChange={(e) => changed(setDate)(e.target.value)} />{' '}
      <input data-testid="claim-form-note" value={note} placeholder="Note" onChange={(e) => changed(setNote)(e.target.value)} />{' '}
      <input
        data-testid="claim-form-corrects"
        value={corrects}
        placeholder="Corrects no."
        inputMode="numeric"
        onChange={(e) => changed(setCorrects)(e.target.value)}
      />{' '}
      <input data-testid="claim-form-ref" value={ref} placeholder="Reference" onChange={(e) => changed(setRef)(e.target.value)} />{' '}
      <input data-testid="claim-form-tags" value={tags} placeholder="Tags" onChange={(e) => changed(setTags)(e.target.value)} />{' '}
      <button type="submit" data-testid="claim-form-submit">{editing !== '' ? 'Save claim' : 'Add claim'}</button>
      {save.isError && (
        <span data-testid="claim-form-error" role="alert"> Could not save: the amount must have at most two decimals, a negative amount is a correction that must name by number a SETTLED claim of the same person (and only a correction names one), no claim whose due-by falls inside a closed period can be added or changed, none after the person's retirement date, and no reference already used on the sheet.</span>
      )}
    </form>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The status a change is refused with while the screen is shown as of a date. */
export const AS_OF_REFUSED = 423;

/** Whether the screen is shown as of a date (the `asof` search param, see features/asof): every change is refused. */
function viewingAsOf(): boolean {
  return new URLSearchParams(window.location.search).get('asof') ? true : false;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // An as-of view shows the sheet as it stood: a change asked for from it is refused, as any refused change, and
  // nothing reaches the store.
  if ((init?.method ?? 'GET') !== 'GET' && viewingAsOf()) {
    throw new HttpError(`${init?.method} ${path} -> refused: the screen is shown as of a date`, AS_OF_REFUSED);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

/** Guards a form's submit so a second submit made before the first has answered (a double click)
 *  is ignored: the store gets one record, not two. A ref, not mutation state, so it holds even
 *  for two clicks landing before the next render. */
export function useSubmitOnce(): (run: () => Promise<unknown>) => void {
  const busy = useRef(false);
  return (run) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => {
        // the mutation shows its own error
      })
      .finally(() => {
        busy.current = false;
      });
  };
}

